// Normalise the caller's input and validate it BEFORE anything reaches syschange.
// Everything downstream can then trust these fields.
const body = $json.body ?? {};
const action = String(body.action ?? 'plan').trim().toLowerCase();
const out = { action, valid: true, error: null };

if (!['plan', 'approve'].includes(action)) {
  out.valid = false;
  out.error = {
    code: 'UNKNOWN_ACTION',
    message: `Unsupported action "${action}".`,
    hint: 'Use action "plan" to describe a change, or action "approve" with a run_id.',
  };
} else if (action === 'plan') {
  const request = String(body.request ?? '').trim();
  if (!request) {
    out.valid = false;
    out.error = { code: 'MISSING_REQUEST',
      message: 'A plan needs a "request" describing what you want changed.',
      hint: 'e.g. {"action":"plan","request":"show disk usage"}' };
  } else if (request.length > 2000) {
    out.valid = false;
    out.error = { code: 'REQUEST_TOO_LONG',
      message: `request is ${request.length} characters; the limit is 2000.`,
      hint: 'Describe the change more briefly.' };
  }
  out.request = request;
} else {
  const runId = String(body.run_id ?? '').trim();
  if (!/^run-[A-Za-z0-9-]+$/.test(runId)) {
    out.valid = false;
    out.error = { code: 'BAD_RUN_ID',
      message: 'An approval needs a run_id shaped like "run-xxxxxxxx".',
      hint: 'Copy the run id from the plan response you are approving.' };
  }
  out.run_id = runId;
}
return [{ json: out }];

const a = $json;
const ok = a.exit_code === 0 && Boolean(a.applied);
return [{ json: {
  code: ok ? 200 : 500,
  body: {
    ok,
    kind: 'approval',
    run: { id: a.run_id ?? null, applied: Boolean(a.applied), exit_code: a.exit_code ?? null },
    message: ok
      ? 'Approved and applied.'
      : 'Approval did not complete. Nothing should be assumed to have changed.',
    output: String(a.stdout ?? '').slice(-4000),
    error: ok ? null : { code: 'APPROVE_FAILED', message: String(a.stderr ?? '').slice(0, 600) },
    meta: { execution_id: $execution.id, at: new Date().toISOString() },
  },
} }];

// Turn the shim's plan into a response an operator can act on:
// a human message, an explicit next step, and the risk in plain words.
const s = $json;
const steps = s.steps ?? [];
const risk = String(s.risk ?? 'unknown').toLowerCase();
const needsApproval = Boolean(s.approval_required);
const RISK_WORDS = {
  low: 'Low risk - mostly reads, but syschange still decides what to run.',
  medium: 'Medium risk - some steps change state. Read every command.',
  high: 'High risk - expects sudo or irreversible changes. Read every command.',
  critical: 'Critical risk - treat this as potentially destructive.',
};

return [{ json: {
  code: needsApproval ? 202 : (s.exit_code === 0 ? 200 : 502),
  body: {
    ok: s.exit_code === 0 || needsApproval,
    kind: 'plan',
    run: {
      id: s.run_id ?? null,
      risk,
      risk_note: RISK_WORDS[risk] ?? 'Unrecognised risk level - read every step.',
      step_count: steps.length,
      approval_required: needsApproval,
      applied: Boolean(s.applied),
    },
    steps: steps.map(st => ({ id: st.id, risk: st.risk, command: st.command })),
    // Pre-test evidence: what a scratch run of the step actually did.
    pretest: s.pretest_report || null,
    message: needsApproval
      ? `Planned ${steps.length} step(s) at ${risk} risk. NOTHING HAS BEEN CHANGED YET.`
      : `syschange ran ${steps.length} step(s) at ${risk} risk without hitting an approval gate.`,
    next: needsApproval ? {
      via_api: { action: 'approve', run_id: s.run_id },
      via_cli: `~/ai-system/syschange/syschange-run approve ${s.run_id} --yes`,
      warning: 'Approving executes these commands with your privileges.',
    } : null,
    error: s.error ? { code: 'PLANNER_FAILED', message: String(s.error).slice(0, 600) } : null,
    meta: { execution_id: $execution.id, at: new Date().toISOString() },
  },
} }];

const v = $json;
return [{ json: { code: 400, body: {
  ok: false, kind: 'error',
  error: v.error,
  message: v.error?.message ?? 'Invalid request.',
  meta: { execution_id: $execution.id, at: new Date().toISOString() },
} } }];

const e = $json ?? {};
const detail = e.error?.message ?? e.message ?? 'The sandbox shim did not respond as expected.';
return [{ json: { code: 502, body: {
  ok: false, kind: 'error',
  error: { code: 'SHIM_UNREACHABLE', message: String(detail).slice(0, 600) },
  message: 'Could not reach the sandbox shim on the host.',
  hint: 'Check: systemctl --user status sandbox-shim && ~/sandbox-shim/bridge-check.sh',
  meta: { execution_id: $execution.id, at: new Date().toISOString() },
} } }];
